{"cards": [{"node_code": "N_b0d0b192118334c7", "definition": "研究金属液充入型腔的过程、浇注系统设计，以及通过冒口、冷铁等结构实现补缩和凝固顺序控制的理论与技术。", "boundary": "聚焦于铸造过程中的流体流动与热传导控制，旨在保证铸件致密性。涵盖浇注系统（浇口、内浇道）设计、冒口尺寸计算、冷铁布置及顺序凝固/同时凝固原理。不涉及熔炼前的炉料准备（归入“熔炼、炉料与孕育处理”）或具体的缺陷微观机理分析（归入“凝固收缩、偏析与铸造缺陷”）。", "includes": ["浇注系统（浇包、浇口、内浇道）的设计与优化", "冒口、冷铁、补贴等补缩结构的设计与计算", "充型过程模拟、凝固顺序控制及顺序凝固/同时凝固原理"], "excludes": ["熔炼过程中的炉料配比、熔炼温度控制及孕育剂添加", "铸件凝固后产生的具体缺陷（如气孔、缩松）的微观机理与检测"], "sibling_distinctions": [{"other_code": "N_548e90329fca144c", "rule": "本节点关注金属液进入型腔后的流动与凝固控制（充型/补缩），兄弟节点关注金属液在炉内的制备与成分调整（熔炼/孕育）。"}, {"other_code": "N_604854b2fbb29337", "rule": "本节点关注通过结构设计预防缺陷的工艺手段（如冒口设计），兄弟节点关注缺陷本身的形成机理、分类及微观组织演变。"}], "cross_boundary_rule": "若研究重点在于浇注系统对铸件内部质量的影响，主挂载本节点；若重点在于缺陷的微观形成机制，主挂载“凝固收缩、偏析与铸造缺陷”。"}, {"node_code": "N_548e90329fca144c", "definition": "研究铸造合金的熔炼工艺、炉料选择与配比、熔体净化及通过孕育处理改善组织性能的理论与技术。", "boundary": "聚焦于铸造前的金属液制备阶段，包括熔炼设备、炉料（生铁、废钢、合金）管理、熔炼温度控制、脱气除渣及孕育剂（如硅铁）的添加与反应。不涉及金属液充入型腔后的流动与凝固控制（归入“浇注、冒口与补缩系统”）或铸件后处理。", "includes": ["各类铸造合金（铸铁、铸钢、有色合金）的熔炼工艺与设备", "炉料选择、配料计算、熔炼温度及成分控制", "熔体净化（脱气、除渣）及孕育处理、变质处理技术"], "excludes": ["金属液充入型腔后的浇注系统设计及补缩控制", "铸件凝固过程中的收缩、偏析及缺陷形成机理"], "sibling_distinctions": [{"other_code": "N_b0d0b192118334c7", "rule": "本节点关注金属液在炉内的制备与成分调整（熔炼/孕育），兄弟节点关注金属液进入型腔后的流动与凝固控制（充型/补缩）。"}, {"other_code": "N_604854b2fbb29337", "rule": "本节点关注通过熔炼和孕育手段主动改善组织，兄弟节点关注凝固过程中自然发生的收缩、偏析等物理现象及缺陷。"}], "cross_boundary_rule": "若研究重点在于熔炼工艺对熔体成分和纯净度的影响，主挂载本节点；若重点在于熔体充型后的凝固行为，主挂载“浇注、冒口与补缩系统”。"}, {"node_code": "N_604854b2fbb29337", "definition": "研究金属液凝固过程中的体积收缩、成分偏析机理，以及由此产生的气孔、缩松、裂纹等铸造缺陷的形成、控制与检测技术。", "boundary": "聚焦于凝固物理过程及其导致的宏观/微观缺陷。涵盖液态收缩、凝固收缩、固态收缩的机理，宏观/微观偏析，以及缩孔、缩松、气孔、热裂、冷裂等缺陷的成因分析与预防。不涉及具体的补缩结构设计（归入“浇注、冒口与补缩系统”）或熔炼前的成分调整（归入“熔炼、炉料与孕育处理”）。", "includes": ["金属凝固过程中的收缩机理（液态、凝固、固态）及偏析现象", "常见铸造缺陷（缩孔、缩松、气孔、裂纹、夹渣等）的形成机理", "缺陷的预防工艺措施、检测方法及质量评估"], "excludes": ["浇注系统、冒口等具体补缩结构的设计与计算", "熔炼过程中的炉料配比、熔炼温度及孕育剂添加工艺"], "sibling_distinctions": [{"other_code": "N_b0d0b192118334c7", "rule": "本节点关注缺陷本身的形成机理与分类，兄弟节点关注通过结构设计（如冒口）预防缺陷的工艺手段。"}, {"other_code": "N_548e90329fca144c", "rule": "本节点关注凝固过程中的物理现象及结果，兄弟节点关注熔炼阶段的化学/物理处理及成分控制。"}], "cross_boundary_rule": "若研究重点在于缺陷的微观组织演变及形成机制，主挂载本节点；若重点在于如何通过冒口/冷铁设计消除缺陷，主挂载“浇注、冒口与补缩系统”。"}]}
